/* Files compiled into the program (generated by cmake/embed.cmake): the UI and the bridge script. Each is NUL-terminated, so text files can be used as C strings. */
#ifndef GC_RESOURCES_H
#define GC_RESOURCES_H

#include <stddef.h>

typedef struct gc_resource {
    const char *name; /* "ui/index.html" or "app/bridge.js" */
    const unsigned char *data;
    size_t len;       /* without the trailing NUL */
} gc_resource;

extern const gc_resource gc_resources[];
extern const size_t gc_resource_count;
extern const char GC_VERSION[];

/* Finds a resource by name; the program can't run without the ones it asks for, so a missing one
   is a build error caught at start-up. */
const gc_resource *gc_find_resource(const char *name);

#endif
